using System;using System.IO;using System.Text.Json;using System.Security.Cryptography;using Por.Core;
public static class Program {
 public static void Main(string[] args){GDVars.gameDir=Path.GetFullPath(args[0])+Path.DirectorySeparatorChar;GDVars.virtualDisk=1;GDVars.dsSuppressingInsertDiskFlag=true;DaxIo.ResetArchiveCache();int n=0;using(var doc=JsonDocument.Parse(File.ReadAllText(args[1]))){foreach(var row in doc.RootElement.GetProperty("rows").EnumerateArray()){string file=row.GetProperty("file").GetString();byte id=(byte)row.GetProperty("id").GetInt32();ushort size;byte[] data;DaxIo.LoadDax(file,".DAX",id,out size,out data);if(data==null||size!=row.GetProperty("raw").GetInt32())throw new Exception(file+"#"+id+" size mismatch");string hash=Convert.ToHexString(SHA256.HashData(data)).ToLowerInvariant();if(hash!=row.GetProperty("sha256").GetString())throw new Exception(file+"#"+id+" source-oracle hash mismatch");n++;}}Console.WriteLine("Read-only real DAX blocks matched independent source oracle: "+n);}
}
